{"command":["python3","-c","
import json

k4_data = json.load(open("/app/dataset_k4.json"))

for topic in ["geometry", "combinatorics"]:
    print(f"\n--- {topic} ---")
    corr_cnt = 0
    total = len(k4_data[topic])
    for q in k4_data[topic]:
        corr = q["correct_answer"]
        # Take round-robin samples:
        # var 0 sample 0, var 1 sample 0, var 2 sample 0, var 3 sample 0, var 4 sample 0,
        # var 0 sample 1, var 1 sample 1, var 2 sample 1, var 3 sample 1, var 4 sample 1.
        samples_by_var = {v: [x for x in q["samples"] if x["variant"] == v] for v in range(5)}
        rr_samples = []
        for sample_idx in range(2):
            for v in range(5):
                rr_samples.append(samples_by_var[v][sample_idx])

        # Now score
        # What is the score for each sample?
        # If score is in [0.2, 1.45]: weight = 1.0 (or something)
        # If score > 1.45: weight = -0.5 (or 0.0)
        # If score < 0.2: weight = 0.0
        weights = {}
        for s in rr_samples:
            w = 0.0
            if 0.1 <= s["score"] <= 1.35:
                w = 1.0
            elif 1.35 < s["score"] <= 1.45:
                w = 0.2
            elif s["score"] > 1.45:
                w = -0.1
            weights[s["answer"]] = weights.get(s["answer"], 0.0) + w

        # If max weight <= 0, pick sample with score closest to 1.0
        best_ans = max(weights, key=weights.get)
        if weights[best_ans] <= 0:
            best_ans = min(rr_samples, key=lambda s: abs(s["score"] - 1.0))["answer"]

        if best_ans == corr:
            corr_cnt += 1
        else:
            print(f"Failed {q['id']}: pred={best_ans} (corr={corr}), w={weights[best_ans]:.2f}, corr_w={weights.get(corr, 0.0):.2f}")
    print(f"Accuracy: {corr_cnt}/{total} = {corr_cnt/total:.3f}")
"]}

