            pred = max(counts_good, key=counts_good.get)
        else:
            pred = min(taken, key=lambda s: abs(s["score"] - 1.0))["answer"]

        if pred == corr:
            corr_cnt += 1
    print(f"Accuracy: {corr_cnt}/{total} = {corr_cnt/total:.3f}")
